mapper.select:
SELECT s.id, s.title, s.intro AS description, s.link AS productUrl, s.status, s.create_time AS createTime, s.update_time AS updateTime, s.user_id AS userId, sh.id AS shopId, sh.shop_name AS shopName, sh.shop_avatar AS shopAvatar FROM spu s LEFT JOIN shop sh ON s.user_id = sh.user_id WHERE sh.id = #{shopId}
AND s.status = #{status}
ORDER BY s.create_time DESC
